import{_ as a}from"./chunks/architecture.Cs8uKTTN.js";import{_ as e,o as n,c as i,a2 as p}from"./chunks/framework.CHeM0PsO.js";const E=JSON.parse('{"title":"概念","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/concepts/overview.md","filePath":"zh-CN/concepts/overview.md","lastUpdated":1784903584000}'),t={name:"zh-CN/concepts/overview.md"};function o(l,s,c,r,h,d){return n(),i("div",null,[...s[0]||(s[0]=[p('<h1 id="概念" tabindex="-1">概念 <a class="header-anchor" href="#概念" aria-label="Permalink to &quot;概念&quot;">​</a></h1><h2 id="架构" tabindex="-1">架构 <a class="header-anchor" href="#架构" aria-label="Permalink to &quot;架构&quot;">​</a></h2><p>swag2mcp 充当 API 规范和 LLM 智能体之间的桥梁：</p><img src="'+a+`" width="800" alt="swag2mcp 架构"><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><p><strong>Spec</strong> — 代表 API 域或服务的逻辑容器（例如 YouTube、Binance、Open-Meteo）。每个 spec 有唯一的 <code>domain</code>、<code>base_url</code>、可选的 <code>auth</code>，并包含一个或多个 collection。你还可以设置 <code>llm_instruction</code> — 注入到 swag2mcp 系统提示中的简短提示，告诉 LLM 此 spec 的用途以及何时使用。了解更多：<a href="./specs">Specs</a>。</p><p><strong>Collection</strong> — 描述特定 API 的单个 OpenAPI/Swagger/Postman 文件。它指向一个 <code>location</code>（URL 或本地文件路径）。一个 spec 可以有多个 collection — 例如，&quot;meteo&quot; spec 可能有&quot;Forecast&quot;、&quot;Air Quality&quot;和&quot;Marine&quot; collection，每个指向不同的规范文件。了解更多：<a href="./collections">Collections</a>。</p><p><strong>Tag</strong> — collection 内端点的类别。帮助 LLM 更精确地找到正确的操作。了解更多：<a href="./tags">Tags</a>。</p><p><strong>Endpoint</strong> — 特定的 HTTP 方法 + 路径（例如 <code>GET /api/users</code>）。LLM 可以通过描述找到端点，检查其参数和模式，然后调用它。了解更多：<a href="./endpoints">Endpoints</a>。</p><p><strong>Workspace</strong> — swag2mcp 存储配置、规范缓存、保存的响应和认证脚本的目录。了解更多：<a href="./workspace">Workspace</a>。</p><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><ol><li><p><strong>添加 spec 或 collection</strong> — 在 YAML 配置中定义它（<code>~/.swag2mcp/swag2mcp.yaml</code>）。例如：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">specs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">domain</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">jokes</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    llm_title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Dad Joke API</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    base_url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://icanhazdadjoke.com</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    collections</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">llm_title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Jokes</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        location</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://raw.githubusercontent.com/mmadfox/swag2mcp/main/specs/dadjoke.yaml</span></span></code></pre></div></li><li><p><strong>swag2mcp 解析每个 collection</strong> — 创建标签和端点，为搜索建立索引。</p></li><li><p><strong>LLM 找到正确的端点</strong> — 通过 MCP 工具（<code>search</code>、<code>endpoint_by_tag</code>、<code>inspect</code>），LLM 通过描述搜索匹配的端点，查看其参数和请求模式。</p></li><li><p><strong>LLM 调用端点</strong> — 通过 MCP 工具 <code>invoke</code>，LLM 发送请求。swag2mcp 在发起调用之前，会针对端点的 OpenAPI 模式验证每个输入参数（路径参数、查询参数、头、请求体）。如果某些内容与模式不匹配，LLM 会收到清晰的错误说明问题所在。验证通过后，swag2mcp 执行真实的 HTTP 调用并返回结果。</p></li><li><p><strong>结果返回给 LLM</strong> — API 响应被传回给智能体。大响应保存到工作区，可以使用三个专用的 MCP 工具进行探索：<code>response_outline</code>（查看结构）、<code>response_compress</code>（缩小为代表性样本）和 <code>response_slice</code>（提取特定片段）。</p></li></ol><p>swag2mcp 是 LLM 和 API 世界之间的桥梁。你添加 API 规范，LLM — 通过 MCP 协议 — 找到正确的端点，检查其文档，并调用它们。你只需要添加一个 spec 并启动 MCP 服务器。</p><blockquote><p><strong>配置随时可编辑。</strong> YAML 配置文件（<code>~/.swag2mcp/swag2mcp.yaml</code>）可以手动编辑 — 添加 spec、更改认证、调整设置。每次编辑后，重启 MCP 服务器（<code>swag2mcp mcp</code>）以使更改生效。</p></blockquote><h2 id="层次结构" tabindex="-1">层次结构 <a class="header-anchor" href="#层次结构" aria-label="Permalink to &quot;层次结构&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Spec (domain, e.g. &quot;meteo&quot;)</span></span>
<span class="line"><span>  └── Collection 1 (spec file, e.g. forecast.yml)</span></span>
<span class="line"><span>        └── Tag 1 (category)</span></span>
<span class="line"><span>              └── Endpoint (GET /api/forecast)</span></span>
<span class="line"><span>              └── Endpoint (POST /api/forecast)</span></span>
<span class="line"><span>        └── Tag 2</span></span>
<span class="line"><span>              └── Endpoint (GET /api/forecast/{id})</span></span>
<span class="line"><span>  └── Collection 2 (spec file, e.g. air-quality.yml)</span></span>
<span class="line"><span>        └── Tag 3</span></span>
<span class="line"><span>              └── Endpoint (GET /api/air-quality)</span></span></code></pre></div>`,16)])])}const m=e(t,[["render",o]]);export{E as __pageData,m as default};
